(()=>{'use strict';const svg=p=>'<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">'+p+'</svg>';window.airIcons={play:svg('<path d="M8 5.7c0-1 1.1-1.6 1.9-1.1l10 6.3a1.3 1.3 0 010 2.2l-10 6.3A1.3 1.3 0 018 18.3z"/>'),pause:svg('<rect x="6" y="5" width="4" height="14" rx="1.5"/><rect x="14" y="5" width="4" height="14" rx="1.5"/>')};
const buttons=[...document.querySelectorAll('.play')];if(buttons.length){const audio=new Audio('/assets/preview-0.wav');audio.loop=true;audio.volume=.65;const status=document.querySelector('.player-status');const sync=()=>{buttons.forEach(b=>{b.innerHTML=window.airIcons[audio.paused?'play':'pause'];b.setAttribute('aria-pressed',String(!audio.paused));b.setAttribute('aria-label',audio.paused?'Слушать музыкальный эскиз':'Пауза')});document.body.classList.toggle('is-playing',!audio.paused)};sync();if(status)status.textContent='Soul / Jazz · музыкальный эскиз';buttons.forEach(b=>b.onclick=async()=>{if(!audio.paused){audio.pause();status.textContent='Пауза · музыкальный эскиз'}else{try{await audio.play();status.textContent='Играет · музыкальный эскиз'}catch{status.textContent='Не удалось включить аудио. Попробуйте ещё раз.'}}sync()});audio.addEventListener('error',()=>{status.textContent='Аудио временно недоступно';sync()});const volume=document.querySelector('#volume');if(volume)volume.oninput=e=>{audio.volume=+e.target.value/100;document.querySelector('#volume-value').textContent=e.target.value+'%'};const note=document.querySelector('.dash-main>.fine');if(note)note.textContent='Музыкальный эскиз. Управление заведением показано в деморежиме.'}
// Animate only when visible, respect reduced motion and avoid touch parallax.
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced&&'IntersectionObserver'in window){const obs=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('in-view',e.isIntersecting)),{threshold:.12});document.querySelectorAll('.page-visual,.hero-art,.music-card,.radio-art').forEach(el=>{el.classList.add('motion-ready');obs.observe(el)})}
if(!reduced&&matchMedia('(hover:hover) and (pointer:fine)').matches){document.querySelectorAll('.music-card').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.setProperty('--rx',((e.clientY-r.top)/r.height-.5)*-6+'deg');el.style.setProperty('--ry',((e.clientX-r.left)/r.width-.5)*7+'deg')});el.addEventListener('pointerleave',()=>{el.style.setProperty('--rx','0deg');el.style.setProperty('--ry','0deg')})})}
})();
